      <div class="toolgroup" role="group" aria-label="Zoom">${sa("zoom-out","zoom-out","Zoom out","Zoom out · −","-")}${sa("fit","fit","Fit","Fit marker · 0","0")}${sa("zoom-in","zoom-in","Zoom in","Zoom in · +","+")}</div>
