      <div id="nest-progress" class="nest-progress" aria-label="Nesting progress" role="status" aria-live="polite" hidden><div class="nest-progress-row"><span id="nest-progress-time">Starting…</span><button type="button" id="nest-cancel" class="small" hidden>${O("stop")}Cancel search</button></div><progress id="nest-progress-bar" max="1" value="0" aria-label="Search time used"></progress><div class="nest-progress-row"><span>Best so far</span><strong id="nest-progress-best">No valid marker yet</strong></div><span id="nest-cancel-note" class="hint" hidden>The search stops at the time limit.</span></div>
